pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        try c.owned() { assertTrue(msg.sender == c.owner()); } catch { assertTrue(msg.sender != c.owner()); }
    }
}
